// Odległość edycyjna + lista operacji. Napisy w osobnych liniach (mogą być puste).
#include <bits/stdc++.h>
using namespace std;

int main() {
    string a, b;
    getline(cin, a);
    getline(cin, b);
    int n = a.size(), m = b.size();
    vector<vector<int>> dp(n + 1, vector<int>(m + 1));
    for (int i = 0; i <= n; i++) dp[i][0] = i;
    for (int j = 0; j <= m; j++) dp[0][j] = j;
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= m; j++)
            dp[i][j] = min({dp[i - 1][j] + 1,                            // usuń a[i-1]
                            dp[i][j - 1] + 1,                            // wstaw b[j-1]
                            dp[i - 1][j - 1] + (a[i - 1] != b[j - 1])}); // zamień / zgodne
    cout << dp[n][m] << "\n";

    vector<string> ops;                       // odtwarzanie od (n, m)
    int i = n, j = m;
    while (i > 0 || j > 0) {
        if (i > 0 && j > 0 && dp[i][j] == dp[i - 1][j - 1] + (a[i - 1] != b[j - 1])) {
            if (a[i - 1] != b[j - 1]) ops.push_back(string("zamień ") + a[i - 1] + " na " + b[j - 1]);
            i--; j--;
        } else if (i > 0 && dp[i][j] == dp[i - 1][j] + 1) {
            ops.push_back(string("usuń ") + a[i - 1]); i--;
        } else {
            ops.push_back(string("wstaw ") + b[j - 1]); j--;
        }
    }
    reverse(ops.begin(), ops.end());
    for (auto &op : ops) cout << op << "\n";
}

