// Mnożenie łańcucha macierzy: A_i ma wymiary p[i-1] x p[i]. Minimalna liczba mnożeń skalarnych
// i optymalne nawiasowanie.
#include <bits/stdc++.h>
using namespace std;

vector<vector<int>> cut;

string show(int l, int r) {
    if (l == r) return "A" + to_string(l);
    return "(" + show(l, cut[l][r]) + show(cut[l][r] + 1, r) + ")";
}

int main() {
    int n;
    cin >> n;
    vector<long long> p(n + 1);
    for (auto &x : p) cin >> x;
    vector<vector<long long>> dp(n + 1, vector<long long>(n + 1, 0));
    cut.assign(n + 1, vector<int>(n + 1, 0));
    for (int len = 2; len <= n; len++)              // KOLEJNOŚĆ: po długości przedziału
        for (int l = 1; l + len - 1 <= n; l++) {
            int r = l + len - 1;
            dp[l][r] = LLONG_MAX;
            for (int k = l; k < r; k++) {           // ostatnie mnożenie: (A_l..A_k)(A_k+1..A_r)
                long long c = dp[l][k] + dp[k + 1][r] + p[l - 1] * p[k] * p[r];
                if (c < dp[l][r]) { dp[l][r] = c; cut[l][r] = k; }
            }
        }
    cout << dp[1][n] << "\n" << show(1, n) << "\n";
}

// Łączenie sąsiednich stosów: połączenie kosztuje sumę obu stosów. Minimalny koszt złączenia wszystkich.
#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<long long> a(n), P(n + 1, 0);
    for (int i = 0; i < n; i++) { cin >> a[i]; P[i + 1] = P[i] + a[i]; }   // sumy prefiksowe
    vector<vector<long long>> dp(n, vector<long long>(n, 0));
    for (int len = 2; len <= n; len++)
        for (int l = 0; l + len - 1 < n; l++) {
            int r = l + len - 1;
            dp[l][r] = LLONG_MAX;
            for (int k = l; k < r; k++)
                dp[l][r] = min(dp[l][r], dp[l][k] + dp[k + 1][r]);
            dp[l][r] += P[r + 1] - P[l];          // ostatnie złączenie kosztuje sumę całego przedziału
        }
    cout << dp[0][n - 1] << "\n";
}

