// Komiwojażer: n miast (n >= 2), macierz odległości. Minimalny cykl przez wszystkie miasta + trasa.
#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<vector<int>> d(n, vector<int>(n));
    for (auto &row : d) for (auto &x : row) cin >> x;

    const int INF = 1e9;
    int FULL = (1 << n) - 1;
    vector<vector<int>> dp(1 << n, vector<int>(n, INF)), par(1 << n, vector<int>(n, -1));
    dp[1][0] = 0;                                   // start w mieście 0, odwiedzone = {0}
    for (int mask = 1; mask <= FULL; mask++) {
        if (!(mask & 1)) continue;                  // każda ścieżka zawiera start
        for (int v = 0; v < n; v++) {
            if (!(mask >> v & 1) || dp[mask][v] == INF) continue;
            for (int u = 0; u < n; u++) {
                if (mask >> u & 1) continue;
                int nm = mask | (1 << u);
                if (dp[mask][v] + d[v][u] < dp[nm][u]) {
                    dp[nm][u] = dp[mask][v] + d[v][u];
                    par[nm][u] = v;
                }
            }
        }
    }
    int best = INF, last = -1;
    for (int v = 1; v < n; v++)
        if (dp[FULL][v] != INF && dp[FULL][v] + d[v][0] < best) { best = dp[FULL][v] + d[v][0]; last = v; }
    cout << best << "\n";

    vector<int> path;                               // odtwarzanie po par[][]
    for (int v = last, mask = FULL; v != -1; ) {
        path.push_back(v);
        int pv = par[mask][v];
        mask ^= 1 << v;
        v = pv;
    }
    reverse(path.begin(), path.end());
    for (int v : path) cout << v << " ";
    cout << 0 << "\n";
}

// Przydział: n pracowników, n zadań, koszt c[i][j]. Każdy pracownik dostaje dokładnie jedno zadanie.
// dp[mask] = minimalny koszt przydzielenia zadań z mask pracownikom 0..popcount(mask)-1.
#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<vector<int>> c(n, vector<int>(n));
    for (auto &row : c) for (auto &x : row) cin >> x;
    vector<long long> dp(1 << n, LLONG_MAX);
    dp[0] = 0;
    for (int mask = 0; mask < (1 << n); mask++) {
        if (dp[mask] == LLONG_MAX) continue;
        int worker = __builtin_popcount(mask);      // kolejny pracownik do obsłużenia
        if (worker == n) continue;
        for (int job = 0; job < n; job++)
            if (!(mask >> job & 1))
                dp[mask | (1 << job)] = min(dp[mask | (1 << job)], dp[mask] + c[worker][job]);
    }
    cout << dp[(1 << n) - 1] << "\n";
}

