// Ile liczb z [L, R] ma sumę cyfr podzielną przez K (0 <= L <= R <= 10^18, 1 <= K <= 199)?
#include <bits/stdc++.h>
using namespace std;

int K;
vector<int> dig;                 // cyfry N od najbardziej znaczącej
long long memo[20][200];
bool vis[20][200];

long long go(int pos, int rem, bool tight) {
    if (pos == (int)dig.size()) return rem == 0;   // cała liczba zbudowana
    if (!tight && vis[pos][rem]) return memo[pos][rem];
    long long res = 0;
    int lim = tight ? dig[pos] : 9;
    for (int d = 0; d <= lim; d++)
        res += go(pos + 1, (rem + d) % K, tight && d == lim);
    if (!tight) { vis[pos][rem] = true; memo[pos][rem] = res; }
    return res;
}

long long countUpTo(long long N) {   // liczby z [0, N]
    if (N < 0) return 0;
    dig.clear();
    for (char c : to_string(N)) dig.push_back(c - '0');
    memset(vis, 0, sizeof vis);      // memo zależy od długości N — czyścimy
    return go(0, 0, true);
}

int main() {
    long long L, R;
    cin >> L >> R >> K;
    cout << countUpTo(R) - countUpTo(L - 1) << "\n";
}

