// Podziel ciąg na dokładnie k spójnych fragmentów, minimalizując sumę kwadratów sum fragmentów. O(k·n^2).
#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, k;
    cin >> n >> k;
    vector<long long> a(n), P(n + 1, 0);
    for (int i = 0; i < n; i++) { cin >> a[i]; P[i + 1] = P[i] + a[i]; }
    const long long INF = LLONG_MAX / 4;
    // dp[c][i] = najlepszy koszt podziału prefiksu długości i na c fragmentów
    vector<vector<long long>> dp(k + 1, vector<long long>(n + 1, INF));
    vector<vector<int>> from(k + 1, vector<int>(n + 1, -1));
    dp[0][0] = 0;
    for (int c = 1; c <= k; c++)
        for (int i = c; i <= n; i++)
            for (int j = c - 1; j < i; j++) {             // ostatni fragment = a[j..i)
                if (dp[c - 1][j] == INF) continue;
                long long s = P[i] - P[j];
                if (dp[c - 1][j] + s * s < dp[c][i]) { dp[c][i] = dp[c - 1][j] + s * s; from[c][i] = j; }
