    vector<pair<int,int>> parts;                          // odtworzenie granic
    for (int c = k, i = n; c > 0; c--) { int j = from[c][i]; parts.push_back({j, i}); i = j; }
    reverse(parts.begin(), parts.end());
    for (auto [l, r] : parts) {
        cout << "[";
        for (int t = l; t < r; t++) cout << a[t] << (t + 1 < r ? " " : "");
        cout << "] ";
    }
    cout << "\n";
}

// Liczba sposobów podziału ciągu liczb dodatnich na fragmenty o sumie <= S, modulo 10^9+7. O(n).
#include <bits/stdc++.h>
using namespace std;
const long long MOD = 1'000'000'007;

int main() {
    int n; long long S;
    cin >> n >> S;
    vector<long long> a(n);
    for (auto &x : a) cin >> x;
    vector<long long> dp(n + 1, 0), pre(n + 2, 0);   // pre[i] = dp[0] + ... + dp[i-1]
    dp[0] = 1; pre[1] = 1;
    long long window = 0;
    int j = 0;                                       // najmniejszy początek z sumą a[j..i) <= S
    for (int i = 1; i <= n; i++) {
        window += a[i - 1];
        while (window > S) window -= a[j++];         // dwa wskaźniki (liczby dodatnie)
        // ostatni fragment a[t..i) dla t = j..i-1  =>  dp[i] = dp[j] + ... + dp[i-1]
        dp[i] = (pre[i] - pre[j] + MOD) % MOD;
        pre[i + 1] = (pre[i] + dp[i]) % MOD;
    }
    cout << dp[n] << "\n";
}

