// Iteracyjny DFS (bez rekurencji — bezpieczne dla n = 2*10^5 przy ścieżce).
#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<long long> w(n + 1);
    for (int i = 1; i <= n; i++) cin >> w[i];
    vector<vector<int>> adj(n + 1);
    for (int i = 0; i < n - 1; i++) {
        int a, b;
        cin >> a >> b;
        adj[a].push_back(b);
        adj[b].push_back(a);
    }
    vector<int> order, parent(n + 1, 0);
    vector<int> st = {1};
    parent[1] = -1;
    while (!st.empty()) {                     // kolejność odwiedzin: rodzic przed dziećmi
        int v = st.back(); st.pop_back();
        order.push_back(v);
        for (int u : adj[v]) if (u != parent[v]) { parent[u] = v; st.push_back(u); }
    }
    // dp0[v] = najlepszy wynik w poddrzewie v, gdy v NIE wybrany; dp1[v] — gdy wybrany
    vector<long long> dp0(n + 1, 0), dp1(n + 1, 0);
    for (int i = n - 1; i >= 0; i--) {       // odwrotna kolejność = dzieci przed rodzicem
        int v = order[i];
        dp1[v] += w[v];
        if (parent[v] > 0) {
            int p = parent[v];
            dp0[p] += max(dp0[v], dp1[v]);  // rodzic niewybrany: dziecko dowolnie
            dp1[p] += dp0[v];               // rodzic wybrany: dziecko niewybrane
        }
    }
    cout << max(dp0[1], dp1[1]) << "\n";
}

