// DAG: n wierzchołków, m krawędzi u -> v. Liczba ścieżek 1 -> n (mod 10^9+7) i najdłuższa ścieżka (w krawędziach).
#include <bits/stdc++.h>
using namespace std;
const long long MOD = 1'000'000'007;

int main() {
    int n, m;
    cin >> n >> m;
    vector<vector<int>> adj(n + 1);
    vector<int> indeg(n + 1, 0);
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        indeg[v]++;
    }
    queue<int> q;                                 // algorytm Kahna
    for (int v = 1; v <= n; v++) if (indeg[v] == 0) q.push(v);
    vector<int> topo;
    while (!q.empty()) {
        int v = q.front(); q.pop();
        topo.push_back(v);
        for (int u : adj[v]) if (--indeg[u] == 0) q.push(u);
    }
    // (topo.size() < n oznaczałoby cykl)
    vector<long long> cnt(n + 1, 0);
    vector<int> len(n + 1, -1);                   // -1 = nieosiągalny z 1
    cnt[1] = 1; len[1] = 0;
    for (int v : topo) {                          // poprzedniki v są już policzone
        if (len[v] < 0) continue;
        for (int u : adj[v]) {
            cnt[u] = (cnt[u] + cnt[v]) % MOD;
            len[u] = max(len[u], len[v] + 1);
        }
    }
    cout << cnt[n] << " " << len[n] << "\n";
}

